import json
import pandas as pd
import openpyxl

def clean_val(v):
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        return float(v.replace('$', '').replace(',', '').strip())
    return 0.0

df_quotas = pd.read_csv('/root/data/rep_quotas.csv')
df_quotas['base_quota_usd'] = df_quotas['base_quota_usd'].apply(clean_val)

wb_carry = openpyxl.load_workbook('/root/data/quota_carryover.xlsx')
rate_ws = wb_carry['RateTable']
rates = {rate_ws.cell(r, 1).value: rate_ws.cell(r, 2).value for r in range(2, 22)}
base_ws = wb_carry['BaseRef']
bases = {base_ws.cell(r, 1).value: base_ws.cell(r, 2).value for r in range(2, 22)}

carryovers = {}
for rep_id in rates:
    carryovers[rep_id] = round(rates[rep_id] * bases[rep_id], -3)

bookings = {}
with open('/root/data/bookings.jsonl') as f:
    for line in f:
        if not line.strip(): continue
        d = json.loads(line)
        bookings[d['rep_id']] = bookings.get(d['rep_id'], 0.0) + clean_val(d['arr_usd'])

df_draft = pd.read_csv('/root/data/draft_commission_statements.csv')
draft_comm = dict(zip(df_draft['rep_id'], df_draft['draft_commission_usd'].apply(clean_val)))

reps = sorted(df_quotas['rep_id'].tolist())
for rep_id in reps:
    row = df_quotas[df_quotas['rep_id'] == rep_id].iloc[0]
    name = row['rep_name']
    base = row['base_quota_usd']
    carry = carryovers[rep_id]
    tot_quota = base + carry
    bk = bookings.get(rep_id, 0.0)
    att = bk / tot_quota if tot_quota > 0 else 0.0

    if att < 0.8:
        tier = 'Below Threshold'
        rate = 0.0
    elif att < 1.0:
        tier = 'Base'
        rate = 0.08
    elif att < 1.2:
        tier = 'Accelerator 1'
        rate = 0.10
    elif att < 1.5:
        tier = 'Accelerator 2'
        rate = 0.12
    else:
        tier = 'Accelerator 3'
        rate = 0.15

    comm = bk * rate
    dr_comm = draft_comm.get(rep_id, 0.0)
    delta = dr_comm - comm

    if delta > 0.01:
        flag = 'OVERPAID'
    elif delta < -0.01:
        flag = 'UNDERPAID'
    else:
        flag = 'CORRECT'

    print(f'{rep_id} | {name:15} | Base={base:6.0f} Carry={carry:5.0f} Tot={tot_quota:6.0f} | Book={bk:6.0f} Att={att:.4f} | Tier={tier:15} Rate={rate:.2f} Comm={comm:8.2f} Draft={dr_comm:8.2f} Delta={delta:7.2f} Flag={flag}')
