import json
import pandas as pd
import openpyxl
from decimal import Decimal, ROUND_HALF_UP

def clean_val(v):
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        return float(v.replace('$', '').replace(',', '').strip())
    return 0.0

def excel_round(val, decimals=0):
    factor = 10 ** abs(decimals)
    q = Decimal(str(val)) / Decimal(str(factor))
    r = q.to_integral_value(rounding=ROUND_HALF_UP)
    return float(r * factor)

df_quotas = pd.read_csv('/root/data/rep_quotas.csv')
df_quotas['base_quota_usd'] = df_quotas['base_quota_usd'].apply(clean_val)

wb_carry = openpyxl.load_workbook('/root/data/quota_carryover.xlsx')
rate_ws = wb_carry['RateTable']
rates = {rate_ws.cell(r, 1).value: rate_ws.cell(r, 2).value for r in range(2, 22)}
base_ws = wb_carry['BaseRef']
bases = {base_ws.cell(r, 1).value: base_ws.cell(r, 2).value for r in range(2, 22)}

bookings = {}
with open('/root/data/bookings.jsonl') as f:
    for line in f:
        if not line.strip(): continue
        d = json.loads(line)
        bookings[d['rep_id']] = bookings.get(d['rep_id'], 0.0) + clean_val(d['arr_usd'])

for rep_id in sorted(rates.keys()):
    p_carry = round(rates[rep_id] * bases[rep_id], -3)
    e_carry = excel_round(rates[rep_id] * bases[rep_id], -3)
    if p_carry != e_carry:
        # Check if this changes anything
        base = clean_val(df_quotas[df_quotas['rep_id'] == rep_id].iloc[0]['base_quota_usd'])
        bk = bookings.get(rep_id, 0.0)
        for label, carry in [('python', p_carry), ('excel', e_carry)]:
            tot = base + carry
            att = bk / tot
            if att < 0.8:
                tier, rate = 'Below Threshold', 0.0
            elif att < 1.0:
                tier, rate = 'Base', 0.08
            elif att < 1.2:
                tier, rate = 'Accelerator 1', 0.10
            elif att < 1.5:
                tier, rate = 'Accelerator 2', 0.12
            else:
                tier, rate = 'Accelerator 3', 0.15
            comm = bk * rate
            print(f'{rep_id} ({label}): carry={carry}, tot={tot}, att={att:.4f}, tier={tier}, comm={comm}')
"

